INSERT INTO `chat_message` (
    id, conversation_id, sender_id, message_type, content, sent_at
) VALUES (
    #{id}, #{conversationId}, #{senderId}, #{messageType}, #{content}, #{sentAt}
)

mapper.select:
SELECT COUNT(1)
FROM `chat_message`
WHERE conversation_id = #{conversationId}

      AND sent_at >= #{startTime}


      AND sent_at <= #{endTime}

SELECT cm.id AS message_id, cm.conversation_id, cm.sender_id, u.username AS sender_name, u.avatar_url AS sender_avatar, cm.message_type, cm.content, cm.sent_at FROM `chat_message` cm INNER JOIN `user` u ON u.id = cm.sender_id AND u.deleted_at IS NULL WHERE cm.conversation_id = #{conversationId}
AND cm.sent_at >= #{startTime}
AND cm.sent_at <= #{endTime}
ORDER BY cm.sent_at DESC, cm.id DESC LIMIT #{offset}, #{limit}
